class.description:
A [FilesManifestValidation] is returned by [method FilesManifestServer.validate]. It lists what is missing or unknown in one [FilesManifest]: folders of [member FilesManifest.folder_paths] and files of [member FilesManifest.file_paths] that do not exist, and extensions of [member FilesManifest.extensions] that no resource loader recognizes. It is read-only after creation.
[codeblocks]
[gdscript]
var validation := FilesManifestServer.validate("mods")
if validation.error == ERR_FILE_NOT_FOUND:
	FilesManifestServer.create_missing_folders("mods")
[/gdscript]
[csharp]
FilesManifestValidation validation = FilesManifestServer.Validate("mods");
if (validation.Error == Error.FileNotFound)
{
    FilesManifestServer.CreateMissingFolders("mods");
}
[/csharp]
[/codeblocks]
